#include <iostream>
using namespace std;

int main() {
    long long n, k;
    cin >> n >> k;

    long long ans = 1;
    for (long long x = 1; x < 10000000; ++x) {
        if ((x / k) * (x % k) == n) {
            ans = x;
            break;
        }
    }

    cout << ans << '\n';
    return 0;
}

